<script setup lang="ts">import{ref,computed}from'vue';import{Head,router}from'@inertiajs/vue3';import{CalendarRange,ClockAlert,FileSpreadsheet,UserCheck}from'@lucide/vue';import AppLayout from '@/Layouts/AppLayout.vue';import PageHeader from '@/Components/DesignSystem/PageHeader.vue';const p=defineProps<{rows:any[],month:string}>();const month=ref(p.month);const activeFilter=ref<'all'|'present'|'late'>('all');const visibleRows=computed(()=>activeFilter.value==='all'?p.rows:p.rows.filter(x=>Number(activeFilter.value==='present'?x.presentDays:x.lateDays)>0));const load=()=>router.get('/dashboard/pegawai/laporan',{month:month.value},{preserveState:true,replace:true});</script>
<template><Head title="Laporan Pegawai"/><AppLayout><main class="mx-auto max-w-7xl space-y-6 p-4"><PageHeader hide-mobile-icon title="Laporan Pegawai" section="Pegawai / Laporan Absensi" description="Ringkasan kehadiran dan kedisiplinan pegawai per bulan."><template #icon><FileSpreadsheet class="h-6 w-6"/></template><template #actions><label class="flex items-center gap-2"><span class="sr-only">Pilih bulan laporan</span><CalendarRange class="h-5 w-5 text-pink-500"/><input v-model="month" @change="load" type="month" class="h-10 rounded-xl border bg-white px-4 font-bold dark:bg-slate-900"/></label></template></PageHeader><div class="grid gap-4 md:grid-cols-3"><button type="button" @click="activeFilter='all'" :aria-pressed="activeFilter==='all'" class="rounded-3xl bg-[#dcefed] p-5 text-left text-[#134e4a]"><p class="text-[10px] font-black uppercase tracking-widest text-[#134e4a]">Jumlah Pegawai</p><p class="text-3xl font-black">{{rows.length}}</p></button><button type="button" @click="activeFilter=activeFilter==='present'?'all':'present'" :aria-pressed="activeFilter==='present'" class="rounded-3xl bg-[#d1fae5] p-5 text-left text-[#065f46]"><p class="text-[10px] font-black uppercase tracking-widest text-[#065f46]">Total Hari Hadir</p><p class="text-3xl font-black">{{rows.reduce((a,x)=>a+Number(x.presentDays),0)}}</p></button><button type="button" @click="activeFilter=activeFilter==='late'?'all':'late'" :aria-pressed="activeFilter==='late'" class="rounded-3xl bg-[#fef3c7] p-5 text-left text-[#78350f]"><p class="text-[10px] font-black uppercase tracking-widest text-[#78350f]">Total Keterlambatan</p><p class="text-3xl font-black">{{rows.reduce((a,x)=>a+Number(x.lateDays),0)}}</p></button></div><section class="overflow-hidden rounded-3xl bg-white shadow-sm dark:bg-slate-900"><header class="flex items-center gap-2 border-b p-6 dark:border-slate-800"><FileSpreadsheet class="h-5 w-5 text-pink-500"/><h2 class="font-black">Rekap Bulanan</h2></header><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b text-[10px] uppercase tracking-widest text-slate-500 dark:border-slate-800"><th class="p-4 pl-7">Pegawai</th><th>Peran</th><th class="text-center">Hari Hadir</th><th class="text-center">Terlambat</th><th class="text-center">Belum Check-out</th></tr></thead><tbody><tr v-if="!visibleRows.length"><td colspan="5" class="p-8 text-center text-slate-500">Tidak ada data untuk filter ini.</td></tr><tr v-for="x in visibleRows" class="border-b last:border-0 dark:border-slate-800"><td class="p-4 pl-7 font-black">{{x.fullName}}</td><td><span class="rounded-full bg-slate-100 px-3 py-1 text-[10px] font-bold dark:bg-slate-800">{{x.role}}</span></td><td class="text-center"><span class="inline-flex items-center gap-1 font-black text-emerald-600"><UserCheck class="h-4 w-4"/>{{x.presentDays}}</span></td><td class="text-center"><span class="inline-flex items-center gap-1 font-black text-amber-600"><ClockAlert class="h-4 w-4"/>{{x.lateDays}}</span></td><td class="text-center font-black text-rose-600">{{x.incompleteDays}}</td></tr></tbody></table></div></section></main></AppLayout></template>
